/* Suspension Lab — workshop testing lab (13 inspection tests, fault simulator, mystery-fault challenge) and MCQ (45 questions).
   Text order in every triple: [English, Gujarati, Hindi]. */
'use strict';

const FAULTS = [
  { id: 'none', n: ['✅ No fault (healthy suspension)', '✅ કોઈ ખામી નહીં (સારું સસ્પેન્શન)', '✅ कोई खराबी नहीं (अच्छा सस्पेंशन)'], d: ['Car rides level, quiet and straight; even tyre wear.', 'ગાડી સમતલ, શાંત અને સીધી ચાલે; ટાયર સરખા ઘસાય.', 'गाड़ी समतल, शांत और सीधी चले; टायर एकसमान घिसें.'] },
  { id: 'damper', n: ['Worn shock absorber (damper)', 'ઘસાયેલું શોક એબ્ઝોર્બર (ડેમ્પર)', 'घिसा शॉक एब्ज़ॉर्बर (डैम्पर)'], d: ['Car keeps bouncing after bumps, nose-dives under braking, floaty at speed; cupped tyre wear; oil on the damper body.', 'બમ્પ પછી ગાડી ઉછળતી રહે, બ્રેક મારતાં આગળ નમે, ઝડપે તરતી લાગે; ટાયરમાં ખાડા જેવો ઘસારો; ડેમ્પર પર તેલ.', 'बम्प के बाद गाड़ी उछलती रहे, ब्रेक पर आगे झुके, तेज़ी पर तैरती लगे; टायर में गड्ढेदार घिसाव; डैम्पर पर तेल.'] },
  { id: 'spring', n: ['Broken coil spring', 'તૂટેલી કોઇલ સ્પ્રિંગ', 'टूटी कॉइल स्प्रिंग'], d: ['One corner sits low, clunk over bumps, car leans; the broken coil end can cut the tyre.', 'એક ખૂણો નીચો, બમ્પ પર ખટાક અવાજ, ગાડી એક બાજુ નમે; તૂટેલો છેડો ટાયર કાપી શકે.', 'एक कोना नीचा, बम्प पर खटाक, गाड़ी एक ओर झुके; टूटा सिरा टायर काट सकता है.'] },
  { id: 'sag', n: ['Sagged (weak) spring', 'ઢીલી પડેલી (નબળી) સ્પ્રિંગ', 'ढीली पड़ी (कमज़ोर) स्प्रिंग'], d: ['Low ride height, hits bump stops on loaded trips, headlamps aim up/down, alignment changes.', 'ઊંચાઈ ઓછી, લોડ સાથે બમ્પ-સ્ટોપ અથડાય, હેડલેમ્પનો ખૂણો બદલાય, એલાઇનમેન્ટ બગડે.', 'ऊँचाई कम, लोड के साथ बम्प-स्टॉप टकराए, हेडलैम्प का कोण बदले, अलाइनमेंट बिगड़े.'] },
  { id: 'balljoint', n: ['Worn lower ball joint', 'ઘસાયેલો લોઅર બોલ જોઇન્ટ', 'घिसा लोअर बॉल जॉइंट'], d: ['Knock over bumps, wandering steering, uneven tyre wear. Dangerous — a separated ball joint drops the wheel.', 'બમ્પ પર ઠક-ઠક, સ્ટીયરિંગ ડગમગે, અસમાન ઘસારો. જોખમી — બોલ જોઇન્ટ છૂટે તો વ્હીલ નીકળી જાય.', 'बम्प पर ठक-ठक, स्टीयरिंग डगमगाए, असमान घिसाव. खतरनाक — बॉल जॉइंट छूटे तो पहिया निकल जाए.'] },
  { id: 'bush', n: ['Worn control-arm bush', 'ઘસાયેલું કંટ્રોલ-આર્મ બુશ', 'घिसा कंट्रोल-आर्म बुश'], d: ['Clunk on braking/accelerating, vague steering, pulling under braking, cracked rubber.', 'બ્રેક/એક્સિલરેટર પર ખટાક, ઢીલું સ્ટીયરિંગ, બ્રેક વખતે ખેંચાણ, રબરમાં તિરાડ.', 'ब्रेक/एक्सीलरेटर पर खटाक, ढीला स्टीयरिंग, ब्रेक पर खिंचाव, रबर में दरार.'] },
  { id: 'bearing', n: ['Worn wheel bearing', 'ઘસાયેલી વ્હીલ બેરિંગ', 'घिसी व्हील बेयरिंग'], d: ['Growl/hum that rises with speed and changes when weaving; play at 12–6 o’clock; ABS light possible.', 'ઝડપ સાથે વધતો ગુંજારવ, વળાંકમાં બદલાય; 12–6 વાગ્યે પ્લે; ABS લાઇટ આવી શકે.', 'गति के साथ बढ़ती घरघराहट, मोड़ पर बदले; 12–6 बजे पर प्ले; ABS लाइट आ सकती है.'] },
  { id: 'tierod', n: ['Worn tie-rod end', 'ઘસાયેલો ટાઇ-રોડ એન્ડ', 'घिसा टाई-रॉड एंड'], d: ['Free play in the steering, knock when turning, toe changes → feathered tyre wear.', 'સ્ટીયરિંગમાં ઢીલાશ, વળતાં ઠક-ઠક, ટો બદલાય → પીંછા જેવો ઘસારો.', 'स्टीयरिंग में ढीलापन, मुड़ते समय ठक-ठक, टो बदले → पंख जैसा घिसाव.'] },
  { id: 'droplink', n: ['Broken anti-roll-bar drop link', 'તૂટેલી એન્ટી-રોલ-બાર ડ્રોપ લિંક', 'टूटी एंटी-रोल-बार ड्रॉप लिंक'], d: ['Rattle/knock over small uneven bumps at low speed; more body roll in corners.', 'ધીમી ઝડપે નાના ખાડાઓ પર ખડખડાટ; વળાંકમાં વધુ નમે.', 'धीमी गति पर छोटे गड्ढों पर खड़खड़ाहट; मोड़ पर ज़्यादा झुके.'] },
  { id: 'toe', n: ['Wrong alignment (toe-out)', 'ખોટું એલાઇનમેન્ટ (ટો-આઉટ)', 'गलत अलाइनमेंट (टो-आउट)'], d: ['Car wanders, steering wheel off-centre, inner shoulders of both tyres wear fast.', 'ગાડી ડગમગે, સ્ટીયરિંગ સીધું ન રહે, બંને ટાયરની અંદરની ધાર ઝડપથી ઘસાય.', 'गाड़ी डगमगाए, स्टीयरिंग सीधा न रहे, दोनों टायरों का अंदरूनी किनारा जल्दी घिसे.'] },
  { id: 'mount', n: ['Worn strut top mount / bearing', 'ઘસાયેલું સ્ટ્રટ ટોપ માઉન્ટ / બેરિંગ', 'घिसा स्ट्रट टॉप माउंट / बेयरिंग'], d: ['Creak or clunk when turning the steering at standstill, spring "springs" back (torque steer feel).', 'ઊભી ગાડીમાં સ્ટીયરિંગ ફેરવતાં કિચૂડ/ખટાક, સ્ટીયરિંગ ઝટકાથી પાછું આવે.', 'खड़ी गाड़ी में स्टीयरिंग घुमाने पर चीं-चीं/खटाक, स्टीयरिंग झटके से लौटे.'] },
  { id: 'air', n: ['Leaking air spring', 'લીક થતી એર સ્પ્રિંગ', 'लीक होती एयर स्प्रिंग'], d: ['Corner drops overnight, compressor runs often/long, "suspension fault" warning.', 'રાતભરમાં એક ખૂણો નીચે બેસે, કોમ્પ્રેસર વારંવાર ચાલે, "suspension fault" ચેતવણી.', 'रात भर में एक कोना नीचे बैठे, कंप्रेसर बार-बार चले, "suspension fault" चेतावनी.'] },
  { id: 'tyre', n: ['Low tyre pressure', 'ટાયરમાં ઓછું પ્રેશર', 'टायर में कम प्रेशर'], d: ['Heavy steering, pull to one side, both shoulders wear, more fuel use.', 'ભારે સ્ટીયરિંગ, એક બાજુ ખેંચાણ, બંને ધાર ઘસાય, વધુ ઇંધણ.', 'भारी स्टीयरिंग, एक ओर खिंचाव, दोनों किनारे घिसें, ज़्यादा ईंधन.'] }
];

/* small SVG sketches (corner of the car) */
const SVGW = (inner) => `<svg viewBox="0 0 320 190" class="tx-svg">${inner}</svg>`;
const WHEEL = (cx, cy) => `<circle cx="${cx}" cy="${cy}" r="52" fill="#1b1d20"/><circle cx="${cx}" cy="${cy}" r="26" fill="#9aa1a8"/><circle cx="${cx}" cy="${cy}" r="7" fill="#555"/>`;
const ARR = (x1, y1, x2, y2, c) => `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${c || '#d97400'}" stroke-width="5" stroke-linecap="round" marker-end="url(#ah)" marker-start="url(#ah)"/>`;
const DEFS = '<defs><marker id="ah" viewBox="0 0 10 10" refX="5" refY="5" markerWidth="4" markerHeight="4" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#d97400"/></marker></defs>';

const TESTS = [
  { id: 'height', ic: '📏', n: ['Ride height (all four corners)', 'રાઇડ હાઇટ (ચારે ખૂણા)', 'राइड हाइट (चारों कोने)'], tool: ['Steel tape, level floor', 'સ્ટીલ ટેપ, સમતલ જમીન', 'स्टील टेप, समतल फ़र्श'], spec: ['Within ±10 mm of spec; left–right difference ≤ 10 mm', 'સ્પેક ±10 mm માં; ડાબે–જમણે ફરક ≤ 10 mm', 'स्पेक ±10 mm में; बाएँ–दाएँ अंतर ≤ 10 mm'],
    steps: [['Correct tyre pressures, empty car, full fuel tank, on a level floor.', 'સાચું ટાયર પ્રેશર, ખાલી ગાડી, ભરેલી ટાંકી, સમતલ જમીન.', 'सही टायर प्रेशर, खाली गाड़ी, भरी टंकी, समतल फ़र्श.'], ['Bounce each corner and let it settle.', 'દરેક ખૂણો દબાવી છોડો, સ્થિર થવા દો.', 'हर कोना दबाकर छोड़ें, स्थिर होने दें.'], ['Measure wheel centre → wheel-arch edge at all four corners and compare.', 'ચારે ખૂણે વ્હીલ સેન્ટર → વ્હીલ-આર્કની ધાર માપો અને સરખાવો.', 'चारों कोनों पर व्हील सेंटर → व्हील-आर्च किनारा मापें और तुलना करें.']],
    svg: () => SVGW(DEFS + `<path d="M40 70 Q160 20 280 70 L280 80 L40 80Z" fill="#d97400" opacity=".85"/>${WHEEL(160, 120)}${ARR(230, 120, 230, 66)}<text x="240" y="100" class="tx-t">h</text>`),
    run(f) { const v = { spring: -46, sag: -27, air: -58, tyre: -7 }[f] || 0; const d = v + (Math.random() - 0.5) * 3; return { v: (d > 0 ? '+' : '') + d.toFixed(0), u: 'mm', pass: Math.abs(d) <= 10, note: Math.abs(d) <= 10 ? ['Ride height OK and level.', 'ઊંચાઈ બરાબર અને સમતલ.', 'ऊँचाई ठीक और समतल.'] : ['This corner sits low: check the spring (broken/sagged), air spring or tyre.', 'આ ખૂણો નીચો: સ્પ્રિંગ (તૂટેલી/ઢીલી), એર સ્પ્રિંગ કે ટાયર તપાસો.', 'यह कोना नीचा: स्प्रिंग (टूटी/ढीली), एयर स्प्रिंग या टायर जाँचें.'] }; } },
  { id: 'bounce', ic: '⬇️', n: ['Bounce test', 'બાઉન્સ ટેસ્ટ', 'बाउंस टेस्ट'], tool: ['Hands (body weight)', 'હાથ (શરીરનું વજન)', 'हाथ (शरीर का वज़न)'], spec: ['Comes back and stops in ≤ 1½ movements', '≤ 1½ વારમાં પાછું આવી સ્થિર થાય', '≤ 1½ बार में लौटकर रुके'],
    steps: [['Push the corner of the body down hard 3–4 times in rhythm.', 'બોડીનો ખૂણો 3–4 વાર લયમાં જોરથી દબાવો.', 'बॉडी का कोना 3–4 बार लय में ज़ोर से दबाएँ.'], ['Let go at the bottom and count the up-down movements.', 'નીચે જઈને છોડી દો અને ઉપર-નીચે કેટલી વાર થાય તે ગણો.', 'नीचे जाकर छोड़ें और ऊपर-नीचे कितनी बार हो वह गिनें.'], ['Listen for knocks or squeaks.', 'ઠક-ઠક કે કિચૂડ અવાજ સાંભળો.', 'ठक-ठक या चीं-चीं आवाज़ सुनें.']],
    svg: () => SVGW(DEFS + `<path d="M40 70 Q160 20 280 70 L280 80 L40 80Z" fill="#d97400" opacity=".85"/>${WHEEL(160, 125)}<text x="150" y="30" font-size="30">✋</text>${ARR(165, 8, 165, 58)}`),
    run(f) { const v = f === 'damper' ? 3.5 : f === 'spring' ? 2 : 1; return { v: String(v), u: LX(['cycles', 'વાર', 'बार']), pass: v <= 1.5, note: v <= 1.5 ? ['Damping OK.', 'ડેમ્પિંગ બરાબર.', 'डैम्पिंग ठीक.'] : ['Keeps bouncing → damper has lost its force. Replace dampers in axle pairs.', 'ઉછળતું રહે → ડેમ્પરનું બળ ગયું. ડેમ્પર એક્સલની જોડીમાં બદલો.', 'उछलता रहे → डैम्पर का बल गया. डैम्पर एक्सल की जोड़ी में बदलें.'] }; } },
  { id: 'eusama', ic: '📊', n: ['Shock-absorber tester (EUSAMA grip %)', 'શોક એબ્ઝોર્બર ટેસ્ટર (EUSAMA ગ્રિપ %)', 'शॉक एब्ज़ॉर्बर टेस्टर (EUSAMA ग्रिप %)'], tool: ['Vibration plate tester (MOT / PUC lane)', 'વાઇબ્રેશન પ્લેટ ટેસ્ટર', 'वाइब्रेशन प्लेट टेस्टर'], spec: ['≥ 40 % good · 20–40 % fair · < 20 % fail; left–right difference ≤ 20 %', '≥ 40 % સારું · 20–40 % ઠીક · < 20 % ફેલ; ડાબે–જમણે ફરક ≤ 20 %', '≥ 40 % अच्छा · 20–40 % ठीक · < 20 % फेल; बाएँ–दाएँ अंतर ≤ 20 %'],
    steps: [['Drive one axle onto the plates, engine off, in neutral.', 'એક એક્સલ પ્લેટ પર ચડાવો, એન્જિન બંધ, ન્યુટ્રલ.', 'एक एक्सल प्लेट पर चढ़ाएँ, इंजन बंद, न्यूट्रल.'], ['The plate shakes from 25 Hz down through wheel-hop resonance (~15 Hz).', 'પ્લેટ 25 Hz થી નીચે વ્હીલ-હોપ (~15 Hz) સુધી હલાવે.', 'प्लेट 25 Hz से नीचे व्हील-हॉप (~15 Hz) तक हिलाए.'], ['Minimum tyre force ÷ static force = grip %.', 'ઓછામાં ઓછું ટાયર બળ ÷ સ્ટેટિક બળ = ગ્રિપ %.', 'न्यूनतम टायर बल ÷ स्टैटिक बल = ग्रिप %.']],
    svg: () => SVGW(DEFS + `${WHEEL(160, 95)}<rect x="90" y="150" width="140" height="18" fill="#0a7db4"/>${ARR(250, 165, 250, 125)}<text x="258" y="150" class="tx-t">25 Hz</text>`),
    run(f) { const L = { damper: 18, tyre: 36, spring: 30, sag: 38, bush: 41 }[f] || 64; const v = L + Math.round((Math.random() - 0.5) * 4); return { v: String(v), u: '%', pass: v >= 40, note: v >= 40 ? ['Good road-holding.', 'સારી રોડ-પકડ.', 'अच्छी रोड-पकड़.'] : ['Low grip at wheel-hop → worn damper (or wrong tyre pressure). Unsafe in emergency braking.', 'વ્હીલ-હોપ પર ઓછી ગ્રિપ → ઘસાયેલો ડેમ્પર (કે ખોટું ટાયર પ્રેશર). ઇમરજન્સી બ્રેકિંગમાં જોખમ.', 'व्हील-हॉप पर कम ग्रिप → घिसा डैम्पर (या गलत टायर प्रेशर). इमरजेंसी ब्रेकिंग में खतरा.'] }; } },
  { id: 'balljoint', ic: '🔩', n: ['Ball-joint play', 'બોલ-જોઇન્ટ પ્લે', 'बॉल-जॉइंट प्ले'], tool: ['Jack, pry bar, dial gauge', 'જેક, પ્રાય બાર, ડાયલ ગેજ', 'जैक, प्राई बार, डायल गेज'], spec: ['Vertical play ≤ 0.5 mm (typical); no knock', 'ઊભું પ્લે ≤ 0.5 mm (સામાન્ય); ઠક-ઠક નહીં', 'खड़ा प्ले ≤ 0.5 mm (सामान्य); ठक-ठक नहीं'],
    steps: [['Lift the car under the lower arm so the joint is unloaded (or as the manual says).', 'લોઅર આર્મ નીચે જેક લગાવી જોઇન્ટ પરથી ભાર હટાવો (મેન્યુઅલ પ્રમાણે).', 'लोअर आर्म के नीचे जैक लगाकर जॉइंट से भार हटाएँ (मैनुअल अनुसार).'], ['Dial gauge on the knuckle, lever the arm up and down with a pry bar.', 'નકલ પર ડાયલ ગેજ, પ્રાય બારથી આર્મ ઉપર-નીચે કરો.', 'नकल पर डायल गेज, प्राई बार से आर्म ऊपर-नीचे करें.'], ['Also check the rubber boot for splits and grease loss.', 'રબર બૂટમાં ચીરા કે ગ્રીસ લીક પણ તપાસો.', 'रबर बूट में चीरा या ग्रीस लीक भी जाँचें.']],
    svg: () => SVGW(DEFS + `<line x1="40" y1="140" x2="200" y2="125" stroke="#566575" stroke-width="12" stroke-linecap="round"/><circle cx="205" cy="124" r="14" fill="#9aa1a8" stroke="#333" stroke-width="3"/><rect x="198" y="40" width="20" height="80" fill="#7a4fd6"/>${ARR(120, 175, 120, 145)}<circle cx="260" cy="70" r="22" fill="#fff" stroke="#333" stroke-width="3"/><line x1="260" y1="70" x2="272" y2="58" stroke="#d0261f" stroke-width="3"/>`),
    run(f) { const v = f === 'balljoint' ? 2.1 : 0.15; return { v: v.toFixed(2), u: 'mm', pass: v <= 0.5, note: v <= 0.5 ? ['Ball joint tight.', 'બોલ જોઇન્ટ બરાબર.', 'बॉल जॉइंट ठीक.'] : ['Excessive play → replace the ball joint (or arm) now; a separated joint drops the wheel.', 'વધુ પ્લે → બોલ જોઇન્ટ (કે આર્મ) તરત બદલો; છૂટે તો વ્હીલ નીકળી જાય.', 'ज़्यादा प्ले → बॉल जॉइंट (या आर्म) तुरंत बदलें; छूटे तो पहिया निकल जाए.'] }; } },
  { id: 'bearing', ic: '⚙️', n: ['Wheel-bearing play & noise (12–6 o’clock)', 'વ્હીલ-બેરિંગ પ્લે અને અવાજ (12–6 વાગ્યે)', 'व्हील-बेयरिंग प्ले और आवाज़ (12–6 बजे)'], tool: ['Jack & stand, hands, dial gauge, stethoscope', 'જેક-સ્ટેન્ડ, હાથ, ડાયલ ગેજ, સ્ટેથોસ્કોપ', 'जैक-स्टैंड, हाथ, डायल गेज, स्टेथोस्कोप'], spec: ['No perceptible play (≤ 0.05 mm); spins silently', 'પ્લે નહીં (≤ 0.05 mm); શાંતિથી ફરે', 'प्ले नहीं (≤ 0.05 mm); शांति से घूमे'],
    steps: [['Wheel off the ground. Hold the tyre at 12 and 6 o’clock and rock it.', 'વ્હીલ જમીનથી ઊંચું. ટાયરને 12 અને 6 વાગ્યે પકડી હલાવો.', 'पहिया ज़मीन से ऊपर. टायर को 12 और 6 बजे पकड़कर हिलाएँ.'], ['Play here (not at 3–9) = bearing. Spin the wheel and listen for rumble.', 'અહીં પ્લે (3–9 પર નહીં) = બેરિંગ. વ્હીલ ફેરવી ગડગડાટ સાંભળો.', 'यहाँ प्ले (3–9 पर नहीं) = बेयरिंग. पहिया घुमाकर गड़गड़ाहट सुनें.']],
    svg: () => SVGW(DEFS + `${WHEEL(160, 95)}${ARR(160, 20, 160, 45)}${ARR(160, 170, 160, 145)}<text x="172" y="32" class="tx-t">12</text><text x="172" y="168" class="tx-t">6</text>`),
    run(f) { const v = f === 'bearing' ? 0.40 : 0.02; return { v: v.toFixed(2), u: 'mm', pass: v <= 0.05, note: v <= 0.05 ? ['Bearing OK.', 'બેરિંગ બરાબર.', 'बेयरिंग ठीक.'] : ['Play + growl → replace the hub/bearing unit; torque the hub nut to spec (never re-use a staked nut).', 'પ્લે + ગડગડાટ → હબ/બેરિંગ યુનિટ બદલો; હબ નટ સ્પેક ટોર્કે (સ્ટેક કરેલો નટ ફરી ન વાપરો).', 'प्ले + गड़गड़ाहट → हब/बेयरिंग यूनिट बदलें; हब नट स्पेक टॉर्क पर (स्टेक किया नट दोबारा नहीं).'] }; } },
  { id: 'tierod', ic: '🔧', n: ['Tie-rod end play (3–9 o’clock)', 'ટાઇ-રોડ એન્ડ પ્લે (3–9 વાગ્યે)', 'टाई-रॉड एंड प्ले (3–9 बजे)'], tool: ['Jack & stand, hands', 'જેક-સ્ટેન્ડ, હાથ', 'जैक-स्टैंड, हाथ'], spec: ['No free play', 'કોઈ ઢીલાશ નહીં', 'कोई ढीलापन नहीं'],
    steps: [['Hold the tyre at 3 and 9 o’clock and push-pull (steering direction).', 'ટાયરને 3 અને 9 વાગ્યે પકડી આગળ-પાછળ કરો (સ્ટીયરિંગ દિશા).', 'टायर को 3 और 9 बजे पकड़कर आगे-पीछे करें (स्टीयरिंग दिशा).'], ['A helper watches the tie-rod end and rack inner joint for movement.', 'સહાયક ટાઇ-રોડ એન્ડ અને રેકના અંદરના જોઇન્ટને જુએ.', 'सहायक टाई-रॉड एंड और रैक के अंदरूनी जॉइंट को देखे.']],
    svg: () => SVGW(DEFS + `${WHEEL(160, 95)}${ARR(80, 95, 105, 95)}${ARR(240, 95, 215, 95)}<text x="62" y="80" class="tx-t">9</text><text x="248" y="80" class="tx-t">3</text>`),
    run(f) { const v = f === 'tierod' ? 1.2 : 0; return { v: v.toFixed(1), u: 'mm', pass: v < 0.2, note: v < 0.2 ? ['Steering joints tight.', 'સ્ટીયરિંગ જોઇન્ટ બરાબર.', 'स्टीयरिंग जॉइंट ठीक.'] : ['Free play at the tie-rod end → replace it, then reset the toe on an alignment machine.', 'ટાઇ-રોડ એન્ડમાં ઢીલાશ → બદલો, પછી એલાઇનમેન્ટ મશીન પર ટો સેટ કરો.', 'टाई-रॉड एंड में ढीलापन → बदलें, फिर अलाइनमेंट मशीन पर टो सेट करें.'] }; } },
  { id: 'bush', ic: '⭕', n: ['Control-arm bush inspection', 'કંટ્રોલ-આર્મ બુશ નિરીક્ષણ', 'कंट्रोल-आर्म बुश निरीक्षण'], tool: ['Pry bar, torch, mirror', 'પ્રાય બાર, ટોર્ચ, અરીસો', 'प्राई बार, टॉर्च, दर्पण'], spec: ['No cracks or tears; movement ≤ 1 mm under lever', 'તિરાડ/ફાટ નહીં; લીવરથી હલન ≤ 1 mm', 'दरार/फटन नहीं; लीवर से हलचल ≤ 1 mm'],
    steps: [['Car on a lift, wheels hanging. Inspect the rubber for cracks and offset.', 'ગાડી લિફ્ટ પર. રબરમાં તિરાડ અને ખસી ગયેલું તપાસો.', 'गाड़ी लिफ़्ट पर. रबर में दरार और खिसकाव जाँचें.'], ['Lever gently between arm and subframe; watch the bush move.', 'આર્મ અને સબફ્રેમ વચ્ચે હળવેથી લીવર કરો; બુશની હલચલ જુઓ.', 'आर्म और सबफ़्रेम के बीच हल्के से लीवर करें; बुश की हलचल देखें.'], ['New bushes are tightened at ride height, not with the wheel hanging.', 'નવા બુશ રાઇડ હાઇટ પર કસો, વ્હીલ લટકતું હોય ત્યારે નહીં.', 'नए बुश राइड हाइट पर कसें, पहिया लटका हो तब नहीं.']],
    svg: () => SVGW(DEFS + `<line x1="60" y1="110" x2="250" y2="110" stroke="#566575" stroke-width="14" stroke-linecap="round"/><circle cx="70" cy="110" r="26" fill="#1b1d20"/><circle cx="70" cy="110" r="10" fill="#9aa1a8"/><path d="M58 92 l10 10 l-6 6 l12 8" stroke="#d0261f" stroke-width="3" fill="none"/>`),
    run(f) { const v = f === 'bush' ? 4 : 0.5; return { v: v.toFixed(1), u: 'mm', pass: v <= 1, note: v <= 1 ? ['Bushes healthy.', 'બુશ બરાબર.', 'बुश ठीक.'] : ['Cracked bush moving 4 mm → replace (press tool), torque at ride height, then align.', 'તિરાડવાળું બુશ 4 mm હલે → બદલો (પ્રેસ ટૂલ), રાઇડ હાઇટ પર ટોર્ક, પછી એલાઇનમેન્ટ.', 'दरार वाला बुश 4 mm हिले → बदलें (प्रेस टूल), राइड हाइट पर टॉर्क, फिर अलाइनमेंट.'] }; } },
  { id: 'droplink', ic: '🔗', n: ['Anti-roll-bar link rattle test', 'એન્ટી-રોલ-બાર લિંક ખડખડાટ ટેસ્ટ', 'एंटी-रोल-बार लिंक खड़खड़ाहट टेस्ट'], tool: ['Hands, pry bar', 'હાથ, પ્રાય બાર', 'हाथ, प्राई बार'], spec: ['No play at either ball stud', 'બંને બોલ સ્ટડમાં પ્લે નહીં', 'दोनों बॉल स्टड में प्ले नहीं'],
    steps: [['Wheels on the ground (link loaded). Grip the link and shake it hard.', 'વ્હીલ જમીન પર. લિંક પકડી જોરથી હલાવો.', 'पहिये ज़मीन पर. लिंक पकड़कर ज़ोर से हिलाएँ.'], ['Knock or free movement = worn ball studs.', 'ઠક-ઠક કે ઢીલું = ઘસાયેલા બોલ સ્ટડ.', 'ठक-ठक या ढीला = घिसे बॉल स्टड.']],
    svg: () => SVGW(DEFS + `<path d="M30 150 Q160 120 290 150" stroke="#566575" stroke-width="10" fill="none"/><line x1="230" y1="140" x2="230" y2="60" stroke="#9aa1a8" stroke-width="8"/><circle cx="230" cy="140" r="8" fill="#333"/><circle cx="230" cy="60" r="8" fill="#333"/>${ARR(200, 100, 260, 100)}`),
    run(f) { const bad = f === 'droplink'; return { v: bad ? LX(['KNOCK', 'ઠક-ઠક', 'ठक-ठक']) : 'OK', u: '', pass: !bad, note: bad ? ['Worn drop link → replace both sides; hold the stud with an Allen key while tightening.', 'ઘસાયેલી ડ્રોપ લિંક → બંને બાજુ બદલો; કસતી વખતે સ્ટડને Allen કીથી પકડો.', 'घिसी ड्रॉप लिंक → दोनों ओर बदलें; कसते समय स्टड को Allen की से पकड़ें.'] : ['Links tight.', 'લિંક બરાબર.', 'लिंक ठीक.'] }; } },
  { id: 'align', ic: '📐', n: ['4-wheel alignment check', '4-વ્હીલ એલાઇનમેન્ટ તપાસ', '4-व्हील अलाइनमेंट जाँच'], tool: ['3D / CCD alignment machine', '3D / CCD એલાઇનમેન્ટ મશીન', '3D / CCD अलाइनमेंट मशीन'], spec: ['Camber −1.3…−0.3° · Caster 3.5…6.0° · Total toe 0…+2 mm', 'કેમ્બર −1.3…−0.3° · કેસ્ટર 3.5…6.0° · કુલ ટો 0…+2 mm', 'कैम्बर −1.3…−0.3° · कैस्टर 3.5…6.0° · कुल टो 0…+2 mm'],
    steps: [['Check tyres, pressures, ride height and all joints FIRST — alignment on worn parts is wasted.', 'પહેલાં ટાયર, પ્રેશર, ઊંચાઈ અને બધા જોઇન્ટ તપાસો — ઘસાયેલા ભાગ પર એલાઇનમેન્ટ નકામું.', 'पहले टायर, प्रेशर, ऊँचाई और सभी जॉइंट जाँचें — घिसे भागों पर अलाइनमेंट बेकार.'], ['Mount targets, run-out compensation, caster swing (±20°).', 'ટાર્ગેટ લગાવો, રન-આઉટ કમ્પેન્સેશન, કેસ્ટર સ્વિંગ (±20°).', 'टार्गेट लगाएँ, रन-आउट कम्पेंसेशन, कैस्टर स्विंग (±20°).'], ['Adjust rear first, then front toe with the steering wheel straight.', 'પહેલાં પાછળ, પછી સ્ટીયરિંગ સીધું રાખી આગળનો ટો.', 'पहले पीछे, फिर स्टीयरिंग सीधा रखकर आगे का टो.']],
    svg: () => SVGW(DEFS + `<rect x="60" y="40" width="40" height="110" rx="10" fill="#1b1d20" transform="rotate(-5 80 95)"/><rect x="220" y="40" width="40" height="110" rx="10" fill="#1b1d20" transform="rotate(5 240 95)"/><line x1="40" y1="20" x2="40" y2="170" stroke="#566575" stroke-dasharray="5 5"/><text x="120" y="100" class="tx-t">toe</text>`),
    run(f) { const cam = f === 'sag' ? -1.9 : f === 'balljoint' ? -1.6 : f === 'bush' ? -1.5 : -0.8, cas = f === 'bush' ? 3.1 : 4.6, toe = f === 'toe' ? -3.0 : f === 'tierod' ? 3.4 : 1.0;
      const ok = cam >= -1.3 && cam <= -0.3 && cas >= 3.5 && cas <= 6 && toe >= 0 && toe <= 2;
      return { v: cam.toFixed(1) + '° / ' + cas.toFixed(1) + '° / ' + (toe > 0 ? '+' : '') + toe.toFixed(1), u: 'mm', pass: ok, table: `<table class="tx-tab"><tr><th>${LX(['Camber', 'કેમ્બર', 'कैम्बर'])}</th><th>${LX(['Caster', 'કેસ્ટર', 'कैस्टर'])}</th><th>${LX(['Toe', 'ટો', 'टो'])}</th></tr><tr><td class="${cam >= -1.3 && cam <= -0.3 ? 'g' : 'f'}">${cam.toFixed(1)}°</td><td class="${cas >= 3.5 && cas <= 6 ? 'g' : 'f'}">${cas.toFixed(1)}°</td><td class="${toe >= 0 && toe <= 2 ? 'g' : 'f'}">${toe > 0 ? '+' : ''}${toe.toFixed(1)} mm</td></tr></table>`,
        note: ok ? ['Alignment in spec.', 'એલાઇનમેન્ટ સ્પેકમાં.', 'अलाइनमेंट स्पेक में.'] : ['Out of spec. Fix the worn part / spring first, then adjust (toe at the tie-rods).', 'સ્પેકની બહાર. પહેલાં ઘસાયેલો ભાગ / સ્પ્રિંગ સુધારો, પછી ટાઇ-રોડથી ટો સેટ કરો.', 'स्पेक से बाहर. पहले घिसा भाग / स्प्रिंग ठीक करें, फिर टाई-रॉड से टो सेट करें.'] }; } },
  { id: 'leak', ic: '💧', n: ['Damper leak & damage (visual)', 'ડેમ્પર લીક અને નુકસાન (નજરે)', 'डैम्पर लीक और नुकसान (देखकर)'], tool: ['Torch, rag', 'ટોર્ચ, કપડું', 'टॉर्च, कपड़ा'], spec: ['Dry body (light misting is normal); rod not pitted or bent', 'બોડી સૂકી (હળવો ભેજ ચાલે); રોડ ખાડાવાળો/વાંકો નહીં', 'बॉडी सूखी (हल्की नमी चलेगी); रॉड गड्ढेदार/टेढ़ी नहीं'],
    steps: [['Wipe the damper body clean, drive, and check again.', 'ડેમ્પર બોડી સાફ કરો, થોડું ચલાવી ફરી જુઓ.', 'डैम्पर बॉडी साफ़ करें, थोड़ा चलाकर फिर देखें.'], ['Oil running down = seal failed → damper has lost fluid.', 'તેલ નીચે વહે = સીલ ગઈ → ડેમ્પરનું પ્રવાહી ગયું.', 'तेल नीचे बहे = सील गई → डैम्पर का तरल गया.']],
    svg: () => SVGW(DEFS + `<rect x="140" y="20" width="40" height="150" rx="8" fill="#0a7db4"/><rect x="152" y="0" width="16" height="30" fill="#c4c9cd"/><path d="M180 60 q8 30 0 60" stroke="#6b4f1d" stroke-width="6" fill="none"/>`),
    run(f) { const bad = f === 'damper'; return { v: bad ? LX(['OIL WET', 'તેલથી ભીનું', 'तेल से गीला']) : LX(['DRY', 'સૂકું', 'सूखा']), u: '', pass: !bad, note: bad ? ['Leaking damper → replace in axle pairs with new top-mount kit & bump stop.', 'લીક ડેમ્પર → એક્સલની જોડીમાં બદલો, નવા ટોપ-માઉન્ટ કિટ અને બમ્પ સ્ટોપ સાથે.', 'लीक डैम्पर → एक्सल की जोड़ी में बदलें, नए टॉप-माउंट किट और बम्प स्टॉप के साथ.'] : ['No leak.', 'લીક નથી.', 'लीक नहीं.'] }; } },
  { id: 'mount', ic: '🔄', n: ['Strut top-mount check', 'સ્ટ્રટ ટોપ-માઉન્ટ તપાસ', 'स्ट्रट टॉप-माउंट जाँच'], tool: ['Hand on the spring, helper at the wheel', 'સ્પ્રિંગ પર હાથ, સહાયક સ્ટીયરિંગ પર', 'स्प्रिंग पर हाथ, सहायक स्टीयरिंग पर'], spec: ['Turns smoothly, no clunk or spring jump', 'સરળ ફરે, ખટાક કે સ્પ્રિંગ ઝટકો નહીં', 'आसानी से घूमे, खटाक या स्प्रिंग झटका नहीं'],
    steps: [['Car on its wheels. Helper turns the steering lock to lock slowly.', 'ગાડી વ્હીલ પર. સહાયક ધીમેથી સ્ટીયરિંગ પૂરું ડાબે-જમણે ફેરવે.', 'गाड़ी पहियों पर. सहायक धीरे से स्टीयरिंग पूरा बाएँ-दाएँ घुमाए.'], ['Hand on the coil spring: feel for notchy jumps; listen at the top mount.', 'કોઇલ સ્પ્રિંગ પર હાથ: ઝટકા અનુભવો; ટોપ માઉન્ટ પાસે સાંભળો.', 'कॉइल स्प्रिंग पर हाथ: झटके महसूस करें; टॉप माउंट के पास सुनें.']],
    svg: () => SVGW(DEFS + `<ellipse cx="160" cy="30" rx="60" ry="14" fill="#1b1d20"/><path d="M135 45 l50 12 -50 12 50 12 -50 12 50 12 -50 12" stroke="#c81e1e" stroke-width="6" fill="none"/><path d="M100 30 a60 14 0 0 1 120 0" stroke="#d97400" stroke-width="4" fill="none" marker-end="url(#ah)"/>`),
    run(f) { const bad = f === 'mount'; return { v: bad ? LX(['CLUNK', 'ખટાક', 'खटाक']) : 'OK', u: '', pass: !bad, note: bad ? ['Worn top-mount bearing → replace the mount kit (spring compressor needed!).', 'ઘસાયેલી ટોપ-માઉન્ટ બેરિંગ → માઉન્ટ કિટ બદલો (સ્પ્રિંગ કમ્પ્રેસર જરૂરી!).', 'घिसी टॉप-माउंट बेयरिंग → माउंट किट बदलें (स्प्रिंग कम्प्रेसर ज़रूरी!).'] : ['Top mount OK.', 'ટોપ માઉન્ટ બરાબર.', 'टॉप माउंट ठीक.'] }; } },
  { id: 'airleak', ic: '🎈', n: ['Air-spring pressure-decay test', 'એર-સ્પ્રિંગ પ્રેશર-ઘટાડો ટેસ્ટ', 'एयर-स्प्रिंग प्रेशर-गिरावट टेस्ट'], tool: ['Diagnostic tester (live data), soapy water', 'ડાયગ્નોસ્ટિક ટેસ્ટર (લાઇવ ડેટા), સાબુ પાણી', 'डायग्नोस्टिक टेस्टर (लाइव डेटा), साबुन पानी'], spec: ['Pressure drop ≤ 0.3 bar in 12 h; ride height stable', '12 કલાકમાં ≤ 0.3 bar ઘટાડો; ઊંચાઈ સ્થિર', '12 घंटे में ≤ 0.3 bar गिरावट; ऊँचाई स्थिर'],
    steps: [['Raise to normal level, note each spring pressure from live data.', 'સામાન્ય લેવલે લાવો, લાઇવ ડેટામાં દરેક સ્પ્રિંગનું પ્રેશર નોંધો.', 'सामान्य लेवल पर लाएँ, लाइव डेटा में हर स्प्रिंग का प्रेशर नोट करें.'], ['Leave 12 h, re-read. Spray soapy water on bellows, valve block and fittings.', '12 કલાક રાખો, ફરી વાંચો. બેલો, વાલ્વ બ્લોક અને ફિટિંગ પર સાબુ પાણી છાંટો.', '12 घंटे रखें, फिर पढ़ें. बेलो, वाल्व ब्लॉक और फ़िटिंग पर साबुन पानी छिड़कें.']],
    svg: () => SVGW(DEFS + `<rect x="120" y="30" width="80" height="110" rx="40" fill="#1b1d20"/><circle cx="215" cy="70" r="5" fill="#9fd5ff"/><circle cx="225" cy="60" r="7" fill="#9fd5ff"/><circle cx="238" cy="52" r="9" fill="#9fd5ff"/>`),
    run(f, sys) { if (sys !== 'air') return { v: 'N/A', u: '', pass: true, note: ['This system has steel springs — test not applicable (choose Air suspension).', 'આ સિસ્ટમમાં સ્ટીલ સ્પ્રિંગ છે — ટેસ્ટ લાગુ નથી (એર સસ્પેન્શન પસંદ કરો).', 'इस सिस्टम में स्टील स्प्रिंग है — टेस्ट लागू नहीं (एयर सस्पेंशन चुनें).'] };
      const d = f === 'air' ? 2.4 : 0.1; return { v: d.toFixed(1), u: 'bar', pass: d <= 0.3, note: d <= 0.3 ? ['No leak.', 'લીક નથી.', 'लीक नहीं.'] : ['Bubbles at the bellows crimp → replace the air spring; check compressor duty (overheating).', 'બેલોના ક્રિમ્પ પર પરપોટા → એર સ્પ્રિંગ બદલો; કોમ્પ્રેસર વધુ ગરમ તો નથી ને તપાસો.', 'बेलो के क्रिम्प पर बुलबुले → एयर स्प्रिंग बदलें; कंप्रेसर ज़्यादा गर्म तो नहीं जाँचें.'] }; } },
  { id: 'tyre', ic: '🛞', n: ['Tyre pressure & wear pattern', 'ટાયર પ્રેશર અને ઘસારો', 'टायर प्रेशर और घिसाव'], tool: ['Pressure gauge, tread-depth gauge', 'પ્રેશર ગેજ, ટ્રેડ-ડેપ્થ ગેજ', 'प्रेशर गेज, ट्रेड-डेप्थ गेज'], spec: ['Placard pressure (≈ 2.3 bar cold); tread ≥ 1.6 mm, even across', 'પ્લેકાર્ડ પ્રેશર (≈ 2.3 bar ઠંડું); ટ્રેડ ≥ 1.6 mm, સરખો', 'प्लेकार्ड प्रेशर (≈ 2.3 bar ठंडा); ट्रेड ≥ 1.6 mm, एकसमान'],
    steps: [['Check pressure cold (before driving).', 'ઠંડા ટાયરમાં પ્રેશર તપાસો (ચલાવ્યા પહેલાં).', 'ठंडे टायर में प्रेशर जाँचें (चलाने से पहले).'], ['Read the wear: edges = pressure/camber, feathering = toe, cupping = damper.', 'ઘસારો વાંચો: કિનારી = પ્રેશર/કેમ્બર, પીંછા = ટો, ખાડા = ડેમ્પર.', 'घिसाव पढ़ें: किनारे = प्रेशर/कैम्बर, पंख = टो, गड्ढे = डैम्पर.']],
    svg: () => SVGW(DEFS + `${WHEEL(110, 95)}<circle cx="235" cy="80" r="34" fill="#fff" stroke="#333" stroke-width="3"/><line x1="235" y1="80" x2="252" y2="64" stroke="#d0261f" stroke-width="3"/><text x="214" y="132" class="tx-t">bar</text>`),
    run(f) { const p = f === 'tyre' ? 1.6 : 2.3; return { v: p.toFixed(1), u: 'bar', pass: p >= 2.1, note: p >= 2.1 ? ['Pressure correct.', 'પ્રેશર બરાબર.', 'प्रेशर ठीक.'] : ['Under-inflated → both shoulders wear, heavy steering, overheating. Inflate and find the leak.', 'ઓછી હવા → બંને કિનારી ઘસાય, ભારે સ્ટીયરિંગ, ગરમી. હવા ભરો અને લીક શોધો.', 'कम हवा → दोनों किनारे घिसें, भारी स्टीयरिंग, गर्मी. हवा भरें और लीक ढूँढें.'] }; } }
];

const Lab = (() => {
  const $ = (s) => document.querySelector(s);
  const S = { fault: 'none', cur: TESTS[0].id, res: {}, myst: null, mystTests: 0, played: 0, score: 0 };
  const sysId = () => (window.SuspLab && window.SuspLab.state.sys ? window.SuspLab.state.sys.id : 'macpherson');
  const T = {
    title: ['Testing & diagnosis lab', 'ટેસ્ટિંગ અને નિદાન લેબ', 'टेस्टिंग और निदान लैब'],
    lede: ['Do the same checks a workshop does. Pick a fault (or let the computer hide one), run the tests, read the instrument and decide.', 'વર્કશોપમાં થતી જ તપાસ કરો. ખામી પસંદ કરો (કે કમ્પ્યુટર છુપાવે), ટેસ્ટ કરો, મીટર વાંચો અને નિર્ણય કરો.', 'वर्कशॉप में होने वाली वही जाँच करें. खराबी चुनें (या कंप्यूटर छुपाए), टेस्ट करें, मीटर पढ़ें और निर्णय लें.'],
    fault: ['Fault (simulator)', 'ખામી (સિમ્યુલેટર)', 'खराबी (सिम्युलेटर)'], tests: ['Inspection tests', 'તપાસ ટેસ્ટ', 'जाँच टेस्ट'], run: ['▶ Do the test', '▶ ટેસ્ટ કરો', '▶ टेस्ट करें'], tool: ['Tools', 'સાધન', 'उपकरण'], spec: ['Spec', 'સ્પેક', 'स्पेक'],
    ok: ['✅ OK', '✅ બરાબર', '✅ ठीक'], bad: ['❌ Fault found', '❌ ખામી મળી', '❌ खराबी मिली'], myst: ['🕵️ Mystery-fault challenge', '🕵️ રહસ્ય ખામી પડકાર', '🕵️ रहस्य खराबी चुनौती'], report: ['📋 Test report', '📋 ટેસ્ટ રિપોર્ટ', '📋 टेस्ट रिपोर्ट'],
    mystIntro: ['The computer hides one fault (or maybe none). Run as few tests as you can, then choose your diagnosis.', 'કમ્પ્યુટર એક ખામી છુપાવશે (કે કદાચ કોઈ નહીં). ઓછામાં ઓછા ટેસ્ટ કરી નિદાન પસંદ કરો.', 'कंप्यूटर एक खराबी छुपाएगा (या शायद कोई नहीं). कम से कम टेस्ट करके निदान चुनें.'],
    newM: ['❓ New mystery fault', '❓ નવી રહસ્ય ખામી', '❓ नई रहस्य खराबी'], diag: ['What is your diagnosis?', 'તમારું નિદાન શું છે?', 'आपका निदान क्या है?'], used: ['Tests used', 'ટેસ્ટ વાપર્યા', 'टेस्ट लगाए'], hidden: ['❓ Mystery fault active', '❓ રહસ્ય ખામી ચાલુ', '❓ रहस्य खराबी चालू'],
    right: ['Correct diagnosis! 🏆', 'સાચું નિદાન! 🏆', 'सही निदान! 🏆'], wrong: ['Not quite. The fault was: ', 'ખોટું. ખામી હતી: ', 'गलत. खराबी थी: '], again: ['🔁 Play again', '🔁 ફરી રમો', '🔁 फिर खेलें'], sym: ['Symptoms', 'લક્ષણો', 'लक्षण'],
    test: ['Test', 'ટેસ્ટ', 'टेस्ट'], reading: ['Reading', 'માપ', 'माप'], result: ['Result', 'પરિણામ', 'परिणाम'], prev: ['← Prev', '← પાછળ', '← पीछे'], next: ['Next →', 'આગળ →', 'आगे →']
  };
  function build() {
    const v = $('#view-test'); if (!v) return;
    v.innerHTML = `<div class="view-head"><div><h1>${LX(T.title)}</h1><p class="lede">${LX(T.lede)}</p></div></div><div class="tx-grid"><aside class="panel tx-side" id="txSide"></aside><div class="tx-main" id="txMain"></div></div>`;
    render();
  }
  function render() {
    const side = $('#txSide'), main = $('#txMain'); if (!side) return;
    const row = (t) => { const r = S.res[t.id]; return `<button class="tx-row" data-t="${t.id}" aria-current="${S.cur === t.id}"><i>${t.ic}</i><span>${LX(t.n)}</span><em>${r ? (r.pass ? '✅' : '❌') : ''}</em></button>`; };
    side.innerHTML = `<label class="tx-lbl">${LX(T.fault)}</label>${S.myst ? `<div class="tx-myst-on">${LX(T.hidden)}</div>` : `<select id="txFault" class="tx-sel">${FAULTS.map((f) => `<option value="${f.id}"${f.id === S.fault ? ' selected' : ''}>${LX(f.n)}</option>`).join('')}</select><p class="tx-sym"><b>${LX(T.sym)}:</b> ${LX(FAULTS.find((f) => f.id === S.fault).d)}</p>`}
      <div class="tx-grp">${LX(T.tests)}</div>${TESTS.map(row).join('')}
      <div class="tx-grp">—</div><button class="tx-row" data-t="myst" aria-current="${S.cur === 'myst'}"><i>🕵️</i><span>${LX(T.myst)}</span><em>${S.played ? S.score + '/' + S.played : ''}</em></button>
      <button class="tx-row" data-t="rep" aria-current="${S.cur === 'rep'}"><i>📋</i><span>${LX(T.report)}</span><em>${Object.keys(S.res).length}</em></button>`;
    const fs = $('#txFault'); if (fs) fs.onchange = () => { S.fault = fs.value; S.res = {}; render(); };
    if (S.cur === 'myst') return renderMyst(main);
    if (S.cur === 'rep') { main.innerHTML = `<div class="panel tx-card"><h2>${LX(T.report)}</h2><div class="scroll-x"><table class="tx-tab big"><tr><th>#</th><th>${LX(T.test)}</th><th>${LX(T.reading)}</th><th>${LX(T.spec)}</th><th>${LX(T.result)}</th></tr>${TESTS.map((t, i) => { const r = S.res[t.id]; return `<tr><td>${i + 1}</td><td>${LX(t.n)}</td><td>${r ? r.v + ' ' + r.u : '—'}</td><td>${LX(t.spec)}</td><td>${r ? (r.pass ? LX(T.ok) : LX(T.bad)) : ''}</td></tr>`; }).join('')}</table></div></div>`; return; }
    const t = TESTS.find((x) => x.id === S.cur), r = S.res[t.id], i = TESTS.indexOf(t);
    main.innerHTML = `<div class="panel tx-card"><span class="pill">${LX(T.test)} ${i + 1} / ${TESTS.length}</span><h2>${t.ic} ${LX(t.n)}</h2>
      <div class="tx-meta"><span>🧰 ${LX(T.tool)}: ${LX(t.tool)}</span><span>📐 ${LX(T.spec)}: ${LX(t.spec)}</span></div>
      <div class="tx-lay"><div><ol class="tx-steps">${t.steps.map((s) => `<li>${LX(s)}</li>`).join('')}</ol>${t.svg()}</div>
        <div class="tx-right"><div class="tx-meter"><small>${LX(T.reading)}</small><b id="txV">${r ? r.v : '– – –'}</b><em>${r ? r.u : ''}</em></div>
          <button class="btn accent tx-go" id="txGo">${LX(T.run)}</button><div id="txVer">${r ? verdict(r) : ''}</div></div></div>
      <div class="tx-nav"><button class="btn ghost" id="txPrev">${LX(T.prev)}</button><button class="btn ghost" id="txNext">${LX(T.next)}</button></div></div>`;
    $('#txGo').onclick = () => { const f = S.myst ? S.myst.f : S.fault; const res = t.run(f, sysId()); S.res[t.id] = res; if (S.myst) S.mystTests++; let k = 0; const el = $('#txV'); const iv = setInterval(() => { el.textContent = (Math.random() * 9).toFixed(1); if (++k > 7) { clearInterval(iv); render(); } }, 60); };
    $('#txPrev').onclick = () => { S.cur = TESTS[(i - 1 + TESTS.length) % TESTS.length].id; render(); };
    $('#txNext').onclick = () => { S.cur = TESTS[(i + 1) % TESTS.length].id; render(); };
  }
  function verdict(r) { return `<div class="tx-ver ${r.pass ? 'ok' : 'bad'}"><b>${r.pass ? LX(T.ok) : LX(T.bad)} — ${r.v} ${r.u}</b><p>${LX(r.note)}</p>${r.table || ''}</div>`; }
  function renderMyst(main) {
    if (!S.myst) { main.innerHTML = `<div class="panel tx-card tx-mys"><h2>${LX(T.myst)}</h2><p>${LX(T.mystIntro)}</p><button class="btn accent" id="txNewM">${LX(T.newM)}</button></div>`;
      $('#txNewM').onclick = () => { const pool = FAULTS.filter((f) => f.id !== 'air' || sysId() === 'air'); const f = Math.random() < 0.1 ? 'none' : pool[1 + Math.floor(Math.random() * (pool.length - 1))].id; S.myst = { f }; S.res = {}; S.mystTests = 0; render(); }; return; }
    main.innerHTML = `<div class="panel tx-card tx-mys"><h2>${LX(T.diag)}</h2><p>${LX(T.used)}: <b>${S.mystTests}</b></p><div class="tx-opts">${FAULTS.map((f) => `<button class="tx-opt" data-f="${f.id}">${LX(f.n)}</button>`).join('')}</div><div id="txMfb"></div></div>`;
    main.querySelectorAll('.tx-opt').forEach((b) => b.onclick = () => { const ok = b.dataset.f === S.myst.f; S.played++; if (ok) S.score++; const F = FAULTS.find((f) => f.id === S.myst.f);
      main.querySelectorAll('.tx-opt').forEach((x) => { x.disabled = true; if (x.dataset.f === S.myst.f) x.classList.add('ok'); }); if (!ok) b.classList.add('no');
      $('#txMfb').innerHTML = `<div class="tx-ver ${ok ? 'ok' : 'bad'}"><b>${ok ? LX(T.right) : LX(T.wrong) + LX(F.n)}</b><p>${LX(F.d)} · ${LX(T.used)}: ${S.mystTests}</p></div><button class="btn accent" id="txAgain">${LX(T.again)}</button>`;
      S.myst = null; $('#txAgain').onclick = () => render(); });
  }
  document.addEventListener('click', (e) => { const b = e.target.closest('#txSide .tx-row'); if (!b) return; S.cur = b.dataset.t; render(); if (innerWidth < 900) $('#txMain').scrollIntoView({ behavior: 'smooth', block: 'start' }); });
  return { build, render, S };
})();
window.Lab = Lab;

